// Run page answers + the Search Skill's country list -> one search task per country x language x source type
// With a domain chosen, its module (skills/domains/<domain>.md) is appended to the Search Skill for every task.
const form = $('Run Settings').first().json;
const files = $('Load Search Skill').all();
const texts = $input.all();
const DOMAINS = {"All domains": "", "Healthcare": "healthcare", "Public service": "public_service", "Agriculture": "agriculture", "Education": "education"};
const domainLabel = String(form['Domain'] || 'All domains');
const domain = DOMAINS[domainLabel] || '';
let searchSkill = '', module = '';
texts.forEach((t, i) => {
  const { fileName: name, directory: dir = '' } = files[i].binary.data;
  if (dir.endsWith('/search') && name === 'SKILL.md') searchSkill = t.json.data;
  else if (domain && dir.endsWith('/domains') && name === `${domain}.md`) module = t.json.data;
});
if (!searchSkill) throw new Error('skills/search/SKILL.md not found');
if (domain && !module) throw new Error(`Domain "${domainLabel}": skills/domains/${domain}.md not found`);
const skill = searchSkill + (module ? `\n\n---\n\n# Domain for this run: ${domainLabel}\n\n${module}` : '');
let registry;
try { registry = JSON.parse(searchSkill.match(/```json countries\s*([\s\S]*?)```/)[1]).countries; }
catch (e) { throw new Error('Search Skill: the "json countries" block is missing or is not valid JSON'); }
const list = (v) => (Array.isArray(v) ? v : String(v || '').split(/[,;\n]+/)).map(s => String(s).trim()).filter(Boolean);
const num = (v, d) => (Number(v) > 0 ? Number(v) : d);
const known = (n) => registry.find(c => [c.name, c.iso].some(k => String(k || '').toLowerCase() === n.toLowerCase()));
// a country missing from the Search Skill's list is still searched, in English only
const countries = [...new Map([...list(form['Countries']), ...list(form['Other countries'])]
  .map(n => known(n) || { name: n, iso: '', local_languages: [] }).map(c => [c.name, c])).values()];
if (!countries.length) throw new Error('Run page: choose at least one country');
const TYPES = {"News": "news", "Government reports (PDF)": "gov_report", "Government websites": "gov_website", "Journal papers": "journal", "Conference reports": "conference_report", "Open-source code & data": "open_source"};
const types = list(form['Source types']).map(t => TYPES[t]).filter(Boolean);
const langs = list(form['Search languages']);
const settings = {
  domain, domain_label: domain ? domainLabel : '',
  focus: form['Topic focus'] || '',
  since_year: num(form['Published from (year)'], ''),
  max_results: num(form['Results per search (target)'], 10),
  max_sources: Number(form['Max sources to analyse in depth']) > 0 ? Number(form['Max sources to analyse in depth']) : 0,   // 0 = no budget: analyse all
  min_relevance: Number((String(form['Relevance screen'] || '').match(/[\d.]+/) || ['0.6'])[0]),
  engine: String(form['Search engine'] || 'Codex').startsWith('Single') ? 'api' : 'codex',
};
// order: all countries first, then languages, then source types, so "Max web searches" drops whole source types from the end
const tasks = [];
for (const source_type of types)
  for (const which of ['Local language', 'English']) if (langs.includes(which))
    for (const c of countries)
      for (const language of which === 'English' ? ['en'] : (c.local_languages || []))
        tasks.push({ search_skill: skill, country: c.name, country_code: c.iso || '', language, source_type, ...settings });
if (!tasks.length) throw new Error('Run page: nothing to search. Choose at least one source type and one language');
return tasks.slice(0, num(form['Max web searches'], 6)).map((json) => ({ json }));

// All candidates from all searches of this run, nothing cut. De-duplicate within the run: same URL, same DOI, or the
// same title (another version of one paper: journal page, preprint, repository copy). The other versions' URLs are kept
// on the first one as extra full-text downloads, so the collector can fall back to them.
const all = $input.all().map(i => i.json).filter(c => c && c.url_norm);
const tnorm = (t) => String(t || '').toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const seen = new Map(), list = [];
let merged = 0;
for (const c of all) {
  const doi = String(c.doi || '').toLowerCase().trim(), t = tnorm(c.title);
  const keys = [c.url_norm, doi && 'doi:' + doi, t.length > 25 && 'title:' + t].filter(Boolean);
  const first = keys.map(k => seen.get(k)).find(Boolean);
  if (first) {
    if (first.url_norm !== c.url_norm && !(first.files || []).some(f => f.url === c.url)) {
      first.files = [...(first.files || []), { url: c.url, kind: 'full_text', note: 'another version of this source found in the search' }];
      if (!first.doi && doi) first.doi = c.doi;
      merged++;
    }
    keys.forEach(k => seen.has(k) || seen.set(k, first));
    continue;
  }
  const item = { ...c, title_norm: t };
  keys.forEach(k => seen.set(k, item));
  list.push(item);
}
return [{ json: { list, found: all.length, unique: list.length, versions_merged: merged } }];

// One shape for both ways of starting a run: the run page (answers by field label) and the website (JSON, POST /webhook/ai4sg-run-start)
const t = $input.first().json;
if (!t.body) return [{ json: t }];
const b = t.body;
const pick = (map, keys) => (Array.isArray(keys) ? keys : []).map(k => map[k]).filter(Boolean);
return [{ json: {
  'Domain': { healthcare: 'Healthcare', public_service: 'Public service', agriculture: 'Agriculture', education: 'Education' }[b.domain] || 'All domains',
  'Countries': Array.isArray(b.countries) ? b.countries : [],
  'Other countries': b.other_countries || '',
  'Search languages': pick({ local: 'Local language', en: 'English' }, b.languages),
  'Source types': pick({ news: 'News', gov_report: 'Government reports (PDF)', gov_website: 'Government websites', journal: 'Journal papers', conference_report: 'Conference reports', open_source: 'Open-source code & data' }, b.source_types),
  'Topic focus': b.topic_focus || '',
  'Published from (year)': b.since_year || '',
  'Search engine': b.engine === 'api' ? 'Single API call (fast)' : 'Codex agent (multi-step, slower)',
  'Max web searches': b.max_searches,
  'Results per search (target)': b.results_per_search,
  'Max sources to analyse in depth': b.max_analyse === null || b.max_analyse === undefined ? '' : b.max_analyse,
  'Relevance screen': { broad: 'Broad (0.4)', balanced: 'Balanced (0.6)', strict: 'Strict (0.8)' }[b.screen_level] || 'Balanced (0.6)',
  submittedAt: new Date().toISOString(), formMode: 'website', job_id: String(b.job_id || ''),
} }];
